//! Golden vectors for the `identity-v1-*` refresh-token account, generated by the JS
//! implementation (`scripts/gen-identity-vectors.mjs` -> `fixtures/identity-v1-vectors.json`).
//! Runs everywhere; needs no keychain.

use hpm_s3::{identity_v1_account, identity_v1_tuple_json};
use serde_json::Value;

fn opt(v: &Value, key: &str) -> Option<String> {
    v.get(key).and_then(Value::as_str).map(str::to_owned)
}

#[test]
fn tuple_serialization_and_account_match_js() {
    let fixture: Value = serde_json::from_str(include_str!("../fixtures/identity-v1-vectors.json")).unwrap();
    let vectors = fixture["vectors"].as_array().unwrap();
    assert!(vectors.len() >= 3, "need at least 3 JS golden samples");
    for v in vectors {
        let name = v["name"].as_str().unwrap();
        let input = &v["input"];
        let (url, client, user) = (
            input["url"].as_str().unwrap(),
            input["clientId"].as_str().unwrap(),
            input["osUser"].as_str().unwrap(),
        );
        let (authz, token) = (opt(input, "authorizeUrl"), opt(input, "tokenUrl"));
        let tuple = identity_v1_tuple_json(url, client, authz.as_deref(), token.as_deref(), user).unwrap();
        assert_eq!(tuple, v["tupleJson"].as_str().unwrap(), "tuple bytes differ for {name}");
        let account = identity_v1_account(url, client, authz.as_deref(), token.as_deref(), user).unwrap();
        assert_eq!(account, v["account"].as_str().unwrap(), "account differs for {name}");
        println!("OK {name}: {account}");
    }
}
